exec('#!/usr/bin/env python3\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom html import escape\nfrom xml.sax.saxutils import escape as xml_escape\nimport re\nROOT = Path(__file__).resolve().parent.parent\nBASE = \'https://jinyou1129-bit.github.io/seoul-glow-guide/\'\nTOPICS = [(\'Hydrating serum\',\'Check the texture and full ingredient list.\'), (\'Gentle cleanser\',\'Compare size, texture and directions.\'), (\'Sunscreen\',\'Check SPF, broad-spectrum labeling and directions on the package.\'), (\'Cleansing oil\',\'Check directions and whether the format fits your routine.\'), (\'Moisturizer\',\'Compare textures and ingredients.\'), (\'Toner\',\'Compare fragrance and ingredient lists.\'), (\'Lip care\',\'Check the ingredient list for known irritants.\'), (\'Sheet mask\',\'Read instructions and ingredient list.\'), (\'Exfoliant\',\'Follow instructions and avoid introducing too many new products at once.\'), (\'Ampoule\',\'Compare ingredients, size and price.\')]\ndef main():\n    day = datetime.now(timezone.utc).date()\n    topic, tip = TOPICS[day.toordinal() % len(TOPICS)]\n    heading = topic + \': a Seoul shopping checklist\'\n    posts = ROOT / \'posts\'\n    posts.mkdir(exist_ok=True)\n    path = posts / (day.isoformat() + \'.html\')\n    if not path.exists():\n        content = f"<!doctype html><html lang=\'en\'><head><meta charset=\'utf-8\'><meta name=\'viewport\' content=\'width=device-width,initial-scale=1\'><title>{escape(heading)} | Seoul Glow Guide</title><link rel=\'stylesheet\' href=\'../style.css\'></head><body><header><div class=\'nav wrap\'><a class=\'brand\' href=\'../\'>Seoul Glow Guide</a></div></header><main class=\'wrap\'><article class=\'article\'><p class=\'eyebrow\'>AUTOMATED SHOPPING CHECKLIST \xb7 {day}</p><h1>{escape(heading)}</h1><p>This is a template-generated checklist, not a firsthand product review. Product availability, formulas and prices may change.</p><h2>In store</h2><p>{escape(tip)}</p><ol><li>Set a budget and compare price per unit.</li><li>Read the exact product label, ingredients and instructions. Ask staff if unsure.</li><li>Patch-test new products and stop using them if irritation occurs.</li><li>Bring your passport and ask staff about current tax-refund eligibility before paying.</li></ol><p>For current selection check <a href=\'https://global.oliveyoung.com/\'>Olive Young Global</a>. For tax rules consult <a href=\'https://www.customs.go.kr/english/main.do\'>Korea Customs Service</a>.</p><p><a href=\'../articles.html\'>All guides</a></p></article></main><footer><div class=\'wrap\'>Independent resource \xb7 Not affiliated with Olive Young.</div></footer></body></html>"\n        path.write_text(content, encoding=\'utf-8\')\n    entries=[]\n    for p in sorted(posts.glob(\'*.html\'), reverse=True):\n        match=re.search(r\'<h1>(.*?)</h1>\',p.read_text(encoding=\'utf-8\'))\n        if match: entries.append(f\'<li><a href="posts/{p.name}">{match.group(1)}</a> \xb7 {p.stem}</li>\')\n    links=\'\\n\'.join(entries)\n    (ROOT/\'articles.html\').write_text(\'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>All guides | Seoul Glow Guide</title><link rel="stylesheet" href="style.css"></head><body><header><div class="nav wrap"><a class="brand" href="./">Seoul Glow Guide</a></div></header><main class="wrap"><article class="article"><h1>All guides</h1><p>Automated shopping checklists; not firsthand reviews.</p><ul>\'+links+\'</ul></article></main></body></html>\',encoding=\'utf-8\')\n    index=ROOT/\'index.html\'\n    html=index.read_text(encoding=\'utf-8\')\n    start=\'<!-- POSTS_START -->\'; end=\'<!-- POSTS_END -->\'\n    if html.count(start)!=1 or html.count(end)!=1: raise ValueError(\'Missing unique post markers\')\n    before, tail=html.split(start,1); _, after=tail.split(end,1)\n    index.write_text(before+start+\'<ul>\'+\'\'.join(entries[:5])+\'</ul>\'+end+after,encoding=\'utf-8\')\n    paths=[\'\',\'olive-young-tax-refund-and-shopping-guide.html\',\'top-k-beauty-products.html\',\'korean-skincare-flashcards.html\',\'articles.html\']+[\'posts/\'+p.name for p in sorted(posts.glob(\'*.html\'))]\n    xml=\'<?xml version="1.0" encoding="UTF-8"?>\\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\\n\'+\'\'.join(\'<url><loc>\'+xml_escape(BASE+x)+\'</loc></url>\\n\' for x in paths)+\'</urlset>\\n\'\n    (ROOT/\'sitemap.xml\').write_text(xml,encoding=\'utf-8\')\n    print(\'Published\',path.relative_to(ROOT))\nif __name__ == \'__main__\': main()\n')
